solution.code:
#include <stdio.h>

int main() {
    int burst[] = {5, 3, 8, 6};
    int n = 4;
    int waiting = 0, total_wait = 0, total_turnaround = 0;
    for (int i = 0; i < n; i++) {
        int turnaround = waiting + burst[i];
        total_wait += waiting;
        total_turnaround += turnaround;
        waiting += burst[i];
    }
    printf("Average wait: %.2f\n", (double)total_wait / n);
    printf("Average turnaround: %.2f\n", (double)total_turnaround / n);
    return 0;
}
